  val another: HttpMessageConverter<*> = AnotherHttpMessageConverter()
  return HttpMessageConverters(additional, another)
  }
}
For further control, you can also sub-class HttpMessageConverters and override its
postProcessConverters and/or postProcessPartConverters methods.

